  check(reference.stable(),"encoded path-only control variation is stable");check(EnvironmentControls.state(200,h,"<p>No endpoint &#47;candidate</p>","https://test/candidate",reference,Set.of()).contains("없는 경로와 동일"),"soft 404 encoded path candidate suppressed only when stable");
  check(!EnvironmentControls.reference(EnvironmentControls.sample(200,h,one+"A","https://test/missing-one",Set.of()),EnvironmentControls.sample(200,h,two+"B","https://test/missing-two",Set.of()),true,"").stable(),"real business content change remains unstable");
  check(ReconMetadata.category("https://test/posts/102").equals("객체 접근"),"numeric path ID is object-access metadata");check(ReconMetadata.category("https://test/files/102").equals("파일 처리"),"path ID heuristic preserves stronger file classification");
  String doc="{\"openapi\":\"3.0.3\",\"paths\":{\"/orders/{id}\":{\"get\":{\"parameters\":[{\"in\":\"query\",\"name\":\"q\"}]}},\"/stored\":{\"post\":{\"requestBody\":{\"content\":{\"application/x-www-form-urlencoded\":{\"schema\":{\"$ref\":\"#/components/schemas/Input\"}}}}}}},\"components\":{\"schemas\":{\"Input\":{\"properties\":{\"value\":{\"type\":\"string\"}}}}}}";
  var api=ApiInventory.parse(doc,"https://test/openapi.json");check(api.size()==2,"bounded OpenAPI methods parsed");var template=api.stream().filter(e->e.template()).findFirst().orElseThrow();var post=api.stream().filter(e->e.method().equals("POST")).findFirst().orElseThrow();
  check(template.matches("https://test/orders/123")&&!template.matches("https://other/orders/123"),"template metadata stays origin-specific");check(post.body().contains("value")&&post.contentType().equals("application/x-www-form-urlencoded"),"internal reference and form body retained");check(ApiInventory.draft(post,post.url()).body().equals("value=REPLACE_ME"),"OpenAPI draft uses form encoding and placeholder values");bad(()->ApiInventory.draft(template,template.url()),"unresolved OpenAPI template cannot become request");bad(()->ApiInventory.draft(template,"https://other/orders/123"),"OpenAPI draft rejects other origin");bad(()->ApiInventory.draft(template,"https://test/orders/%7Bid%7D"),"encoded unresolved template rejected");
  check(ReconMetadata.discover("https://test/openapi.json",doc,false).size()==1,"only static documented path enters URL discovery");check(ApiInventory.parse(doc.replace("\"paths\":","\"servers\":[{\"url\":\"https://other\"}],\"paths\":"),"https://test/doc").isEmpty(),"external server metadata never broadens source origin");
  var missing=PassiveFindings.analyze("http://test/page",200,"Content-Type: text/html\nSet-Cookie: SESSION=SECRET; Path=/","hello");check(missing.size()==4,"HTML headers and two cookie attributes observed");check(missing.stream().noneMatch(f->f.evidence().contains("SECRET")),"cookie value never persisted in passive evidence");
  check(PassiveFindings.analyze("http://test/page",200,"Content-Type: text/html\nContent-Security-Policy: default-src 'none'\nX-Content-Type-Options: nosniff\nSet-Cookie: SESSION=SECRET; HttpOnly; SameSite=Lax","hello").isEmpty(),"fixed header/cookie fixture avoids same observations");
  check(PassiveFindings.analyze("https://test/api",200,"Content-Type: application/json","{}").isEmpty(),"JSON APIs do not inherit HTML-only header observations");
  check(PassiveFindings.analyze("https://test/error",500,"Content-Type: application/json","{\"error\":\"BadSqlGrammarException\"}").stream().anyMatch(f->f.rule().contains("오류")),"SQL implementation information recognized");
  StoredFlows flows=new StoredFlows();flows.register("WB_STORE_TEST01");flows.observe("https://test/store?token=SECRET","POST","value=WB_STORE_TEST01",200,"application/json","{}");flows.observe("https://test/read","GET","",200,"text/html","<b>WB_STORE_TEST01</b>");check(flows.views().size()==2&&flows.views().get(1).state().contains("실행 미검증"),"write/read marker connects without execution claim");check(flows.views().stream().noneMatch(f->f.writeUrl().contains("SECRET")),"flow URLs exclude query values");flows.observe("https://other/read","GET","",200,"text/html","WB_STORE_TEST01");check(flows.views().size()==2,"marker cannot link across origins");bad(()->flows.register("short"),"short ambiguous marker rejected");flows.clear();check(flows.views().isEmpty(),"flow reset removes marker metadata");
